import type { ImageSourcePropType } from 'react-native';
import type { AvatarConfig } from '../../types';

/**
 * Avatar render packs. The full 6 skin tones x 3 hair looks (Long / Bob /
 * Blonde) matrix is pre-rendered with Higgsfield as 8-view turnarounds and
 * sliced into transparent frames, so every studio choice maps to a real,
 * distinct pack. packFor is an exact lookup, no approximation.
 *
 * GENERATED by design tooling (scratchpad/build_packs.js). Do not hand-edit
 * the require table; regenerate when packs change.
 */
export interface AvatarPack {
  /** Ordered clockwise, frame 0 = facing the camera. */
  frames: ImageSourcePropType[];
  /** Source aspect ratio, width / height. */
  aspect: number;
}

export const HAIR_LOOK_COUNT = 3;
export const SKIN_TONE_COUNT = 6;

