const clamp = (v: number, hi: number) => (v < 0 ? 0 : v > hi ? hi : v | 0);

export function packFor(avatar?: AvatarConfig | null): AvatarPack {
  const sk = clamp(avatar?.skinTone ?? 0, 5);
  const look = clamp(avatar?.hairLook ?? 0, 2);
  return PACKS[sk][look];
}

export function frontFor(skinTone: number, hairLook: number): ImageSourcePropType {
  return PACKS[clamp(skinTone, 5)][clamp(hairLook, 2)].frames[0];
}

export const DEFAULT_PACK: AvatarPack = PACKS[0][0];
